guards.addition:
# Optional OmniRoute client integration: never silently use the legacy
# path if this deliberately selected relay profile is absent/unavailable.
if (agent.provider or "").strip().lower() == "omniroute-delegated" and (
    _profile is None or _profile.name != "omniroute-delegated"
):
    raise ValueError("omniroute_delegation_profile_unavailable")

# This optional relay integration supports only the reviewed chat contract.
if (agent.provider or "").strip().lower() == "omniroute-delegated" and agent.api_mode != "chat_completions":
    raise ValueError("omniroute_delegation_api_mode_unsupported")
